public class Main {
    public static void main(String[] args) {
        System.out.println("int の最大値 : " + Integer.MAX_VALUE);
        System.out.println("int の最小値 : " + Integer.MIN_VALUE);

        // 最大値を1つ超えると最小値に戻る
        System.out.println("MAX + 1     : " + (Integer.MAX_VALUE + 1));

        System.out.println("parseInt    : " + (Integer.parseInt("12") + 1));
        System.out.println("toString    : " + Integer.toString(-42).length());
        System.out.println("toBinary(5) : " + Integer.toBinaryString(5));

        System.out.println("isDigit('7'): " + Character.isDigit('7'));
        System.out.println("isDigit('a'): " + Character.isDigit('a'));
        System.out.println("Boolean     : " + Boolean.parseBoolean("true"));
    }
}

public class Main {
    public static void main(String[] args) {
        Integer boxed = Integer.valueOf(10);
        int raw = boxed.intValue();

        System.out.println("包んだもの: " + boxed);
        System.out.println("取り出した: " + raw);

        // Number 型で受けられる
        Number n1 = Integer.valueOf(1);
        Number n2 = Double.valueOf(2.5);
        System.out.println(n1 + " " + n2);

        // ラッパーは不変。中身の書き換えはできない
        Integer a = 5;
        a = a + 1;              // 新しい Integer を作って入れ直している
        System.out.println(a);
    }
}

