public class Main {
    static void tryParse(String text) {
        try {
            int n = Integer.parseInt(text);
            System.out.println("[" + text + "] → " + n);
        } catch (NumberFormatException e) {
            System.out.println("[" + text + "] → 変換できません");
        }
    }

    public static void main(String[] args) {
        tryParse("123");
        tryParse("-5");
        tryParse("007");
        tryParse("abc");
        tryParse("1.5");
        tryParse("12a");
        tryParse(" 12");
        tryParse("");
        tryParse("2147483648");
    }
}

