import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        for (int i = 0; i < k; i++) {
            String text = sc.next();
            try {
                System.out.println(Integer.parseInt(text) * 2);
            } catch (NumberFormatException e) {
                System.out.println("変換できません");
            }
        }
    }
}

