public class Main {
    static void check(int value) {
        Integer a = value;
        Integer b = value;
        System.out.println(value + " : == は " + (a == b) + " / equals は " + a.equals(b));
    }

    public static void main(String[] args) {
        check(100);
        check(127);      // 境界の内側
        check(128);      // 境界の外側
        check(-128);
        check(-129);
        check(0);
    }
}

public class Main {
    public static void main(String[] args) {
        Integer n = null;

        // 比較だけなら安全
        System.out.println("null か: " + (n == null));

        // 数として使おうとすると落ちる
        try {
            int x = n;
            System.out.println(x);
        } catch (NullPointerException e) {
            System.out.println("アンボクシングで NullPointerException");
        }

        try {
            System.out.println(n + 1);
        } catch (NullPointerException e) {
            System.out.println("計算式の中でも同じ");
        }
    }
}

